html,body{margin:0;height:100%;background:#0f172a;font-family:'Open Sans',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#e2e8f0;}
*{box-sizing:border-box;}
.wrap{height:calc(var(--appsmith-ui-height)*1px);display:flex;flex-direction:column;overflow:hidden;}
.topbar{flex:0 0 auto;display:flex;align-items:center;justify-content:flex-end;padding:10px 20px;border-bottom:1px solid #1e293b;}
.panes{flex:1 1 auto;display:flex;overflow:hidden;min-height:0;}
/* hierarchy selector */
.hsel{position:relative;}
.hbtn{display:inline-flex;align-items:center;gap:10px;background:#1e293b;border:1px solid #334155;border-radius:8px;padding:8px 14px;font-size:14px;font-weight:600;color:#e2e8f0;cursor:pointer;min-width:180px;justify-content:space-between;}
.hbtn:hover{border-color:#3b82f6;}
.hbtn .chev{color:#94a3b8;font-size:12px;}
.hpop{position:absolute;top:44px;right:0;z-index:60;background:#1e293b;border:1px solid #334155;border-radius:10px;box-shadow:0 12px 30px rgba(0,0,0,.5);padding:6px;min-width:240px;max-height:340px;overflow:auto;}
.hopt{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 12px;border-radius:6px;font-size:14px;color:#cbd5e1;cursor:pointer;}
.hopt:hover{background:#16233b;}
.hopt.on{color:#60a5fa;font-weight:600;}
.hopt .ck{color:#60a5fa;}
/* left pane */
.left{flex:0 0 34%;max-width:460px;border-right:1px solid #1e293b;display:flex;flex-direction:column;min-height:0;}
.search{padding:14px 16px 10px;flex:0 0 auto;}
.search .box{display:flex;align-items:center;gap:8px;background:#1e293b;border:1px solid #334155;border-radius:8px;padding:9px 12px;}
.search input{flex:1;background:transparent;border:0;outline:none;color:#e2e8f0;font-size:14px;}
.search input::placeholder{color:#64748b;}
.tree{flex:1 1 auto;overflow:auto;padding:4px 8px 20px;}
.node{user-select:none;}
.row{display:flex;align-items:center;gap:6px;padding:6px 8px;border-radius:6px;cursor:pointer;font-size:14px;white-space:nowrap;}
.row:hover{background:#16233b;}
.row.sel{background:#1d4ed8;color:#fff;}
.row.sel .cnt{color:#dbeafe;}
.tw{width:16px;flex:0 0 16px;text-align:center;color:#94a3b8;font-size:11px;}
.row.sel .tw{color:#dbeafe;}
.ico{flex:0 0 auto;display:inline-flex;}
.lbl{flex:1 1 auto;overflow:hidden;text-overflow:ellipsis;}
.cnt{color:#94a3b8;font-size:13px;}
.kids{margin-left:14px;border-left:1px solid #1e293b;}
/* right pane */
.right{flex:1 1 auto;min-width:0;display:flex;flex-direction:column;min-height:0;}
.subtabs{display:flex;gap:2px;padding:10px 18px 0;flex:0 0 auto;border-bottom:1px solid #1e293b;}
.subtab{padding:9px 16px;font-size:14px;font-weight:600;color:#94a3b8;cursor:pointer;border-radius:6px 6px 0 0;}
.subtab.on{color:#fff;background:#1e293b;}
.rbody{flex:1 1 auto;overflow:auto;padding:18px 20px 30px;min-height:0;}
.placeholder{padding:60px 20px;text-align:center;color:#64748b;font-style:italic;}
/* common matrix */
.common h4{margin:0 0 12px;font-size:14px;color:#cbd5e1;font-weight:700;}
.matrix{display:inline-grid;grid-template-columns:auto repeat(3,74px);gap:0;background:#111c31;border:1px solid #1e293b;border-radius:10px;overflow:hidden;margin-bottom:22px;}
.matrix .mh{padding:9px 12px;font-size:13px;font-weight:700;color:#cbd5e1;text-align:center;background:#16233b;}
.matrix .mh.l{text-align:left;}
.matrix .mc{padding:8px 12px;text-align:center;border-top:1px solid #1e293b;}
.matrix .mc.l{text-align:left;color:#e2e8f0;font-size:13px;font-weight:600;}
.pill{display:inline-block;min-width:34px;padding:4px 10px;border-radius:14px;font-size:13px;font-weight:700;background:#0f172a;border:1px solid #334155;color:#e2e8f0;}
.pill.tot{background:#1d4ed8;border-color:#1d4ed8;color:#fff;}
.pill.zero{color:#64748b;}
/* accounts table */
table{width:100%;border-collapse:collapse;font-size:13.5px;}
thead th{text-align:left;color:#94a3b8;font-weight:700;padding:11px 14px;border-bottom:1px solid #1e293b;white-space:nowrap;}
tbody td{padding:12px 14px;color:#e2e8f0;border-bottom:1px solid #131f36;vertical-align:top;}
tbody tr:hover td{background:#131f36;}
.link{color:#60a5fa;cursor:pointer;font-weight:600;}
.lastbill{color:#60a5fa;text-decoration:underline;cursor:pointer;}
.badge{display:inline-block;padding:3px 10px;border-radius:12px;font-size:12px;font-weight:600;}
.badge.open{background:rgba(34,197,94,.15);color:#4ade80;}
.badge.closed{background:rgba(148,163,184,.15);color:#94a3b8;}
.acct-empty{padding:44px 10px;text-align:center;color:#64748b;font-style:italic;}
/* location details */
.details h3{margin:0 0 20px;font-size:16px;font-weight:700;color:#f1f5f9;}
.drow{display:flex;align-items:center;gap:24px;padding:9px 0;max-width:420px;}
.drow .dk{flex:1 1 auto;color:#cbd5e1;font-size:14px;}
.drow .dv{flex:0 0 auto;min-width:60px;text-align:left;color:#f1f5f9;font-size:15px;font-weight:700;}
::-webkit-scrollbar{width:10px;height:10px;background:#0f172a;} ::-webkit-scrollbar-thumb{background:#1e293b;border-radius:4px;border:2px solid #0f172a;}

