function esc(s){return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}
var UTILS=["Electric","Naturalgas","Oil2","Sewer","Water"];
var PIN='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 21s-7-6-7-11a7 7 0 0 1 14 0c0 5-7 11-7 11z"/><circle cx="12" cy="10" r="2.5"/></svg>';
var SEARCH='<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#64748b" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="7"/><line x1="21" y1="21" x2="16.5" y2="16.5"/></svg>';

var expanded={}, selId=null, selLabel="", search="", rightTab="accounts", loadingAcct=false;
var NODES={}, ROOTS=[];
var selRoot=null, hopen=false, rootInited=false, autoSelDone=false;

function groupCounts(n){
  var directGroups=0, directLocs=0, nestedGroups=0;
  (n.kids||[]).forEach(function(k){ if(k.locId!=null && (!k.kids||!k.kids.length)) directLocs++; else directGroups++; });
  (function rec(x){ (x.kids||[]).forEach(function(k){ if(!(k.locId!=null && (!k.kids||!k.kids.length))) nestedGroups++; rec(k); }); })(n);
  return { directGroups:directGroups, directLocs:directLocs, nestedGroups:nestedGroups, nestedLocs:leafCount(n) };
}

function buildTree(){
  var rows=(appsmith.model&&appsmith.model.tree)||[];
  NODES={}; ROOTS=[];
  rows.forEach(function(r){
    var id=String(r.id);
    NODES[id]={ id:id, parent:(r.parent_id==null?null:String(r.parent_id)), locId:r.location_id,
      label:(r.name&&r.name!=="")?r.name:(r.loc_desc||("Site "+(r.location_id||""))),
      addr:r.service_address, kids:[] };
  });
  rows.forEach(function(r){
    var n=NODES[String(r.id)];
    var pid=(r.parent_id==null?null:String(r.parent_id));
    if(pid!=null && NODES[pid]) NODES[pid].kids.push(n);
    else ROOTS.push(n);
  });
  // sort children by label
  Object.keys(NODES).forEach(function(k){ NODES[k].kids.sort(function(a,b){ return String(a.label).localeCompare(String(b.label),undefined,{numeric:true}); }); });
  ROOTS.sort(function(a,b){ return String(a.label).localeCompare(String(b.label),undefined,{numeric:true}); });
  // default the hierarchy selector to "Facility" if present, else the first root
  if(!rootInited && ROOTS.length){
    rootInited=true;
    var fac=ROOTS.filter(function(r){ return String(r.label).toLowerCase()==="facility"; })[0];
    selRoot=String(fac?fac.id:ROOTS[0].id);
    expanded[selRoot]=true;
  }
  if(selRoot!=null && !NODES[selRoot]) selRoot=(ROOTS[0]?String(ROOTS[0].id):null);
}

function leafIds(n){
  var out=[];
  (function rec(x){ if(x.locId!=null && (!x.kids||!x.kids.length)) out.push(x.locId); (x.kids||[]).forEach(rec); })(n);
  // group nodes may also carry a locId; include any locId in subtree
  var all=[];
  (function rec2(x){ if(x.locId!=null) all.push(x.locId); (x.kids||[]).forEach(rec2); })(n);
  return all.length?all:out;
}
function leafCount(n){
  var s={};
  (function rec(x){ if(x.locId!=null) s[x.locId]=1; (x.kids||[]).forEach(rec); })(n);
  return Object.keys(s).length;
}

function nodeMatches(n,q){
  if(String(n.label).toLowerCase().indexOf(q)>-1) return true;
  return (n.kids||[]).some(function(k){ return nodeMatches(k,q); });
}

function renderNode(n,depth){
  var q=search.trim().toLowerCase();
  if(q && !nodeMatches(n,q)) return "";
  var hasKids=n.kids&&n.kids.length;
  var isOpen = expanded[n.id] || (q?true:false);
  var cnt=leafCount(n);
  var tw = hasKids ? (isOpen?"▾":"▸") : "";
  var icon = (n.locId!=null && !hasKids) ? ('<span class="ico">'+PIN+'</span>') : "";
  var cntHtml = hasKids ? (' <span class="cnt">('+cnt+')</span>') : "";
  var sel=(selId===n.id)?" sel":"";
  var html='<div class="node">'
    +'<div class="row'+sel+'" data-id="'+esc(n.id)+'"><span class="tw" data-tw="'+esc(n.id)+'">'+tw+'</span>'+icon+'<span class="lbl">'+esc(n.label)+cntHtml+'</span></div>';
  if(hasKids && isOpen){
    html+='<div class="kids">'+n.kids.map(function(k){ return renderNode(k,depth+1); }).join('')+'</div>';
  }
  html+='</div>';
  return html;
}

function commonMatrix(accts){
  // counts by utility x status; Total = distinct accounts
  var stat={}; UTILS.forEach(function(u){ stat[u]={all:0,open:0,closed:0}; });
  var totAll=0,totOpen=0,totClosed=0;
  accts.forEach(function(a){
    var isOpen=String(a["Open/Closed"]||"").toLowerCase().indexOf("open")>-1
      || String(a["Open/Closed"]||"").toLowerCase()==="active";
    totAll++; if(isOpen) totOpen++; else totClosed++;
    var us=String(a.Utility||"").split(",").map(function(s){return s.trim();}).filter(Boolean);
    us.forEach(function(u){
      var key=UTILS.filter(function(x){ return x.toLowerCase()===u.toLowerCase(); })[0];
      if(!key){ if(!stat[u]) stat[u]={all:0,open:0,closed:0}; key=u; }
      stat[key].all++; if(isOpen) stat[key].open++; else stat[key].closed++;
    });
  });
  var rows=Object.keys(stat).filter(function(u){ return stat[u].all>0 || UTILS.indexOf(u)>-1; });
  // keep canonical order then extras
  rows.sort(function(a,b){ var ia=UTILS.indexOf(a),ib=UTILS.indexOf(b); if(ia<0)ia=99;if(ib<0)ib=99; return ia-ib; });
  function pill(v,cls){ return '<span class="pill '+(cls||"")+(v===0?" zero":"")+'">'+v+'</span>'; }
  var h='<div class="common"><h4>Common</h4><div class="matrix">'
    +'<div class="mh l">&nbsp;</div><div class="mh">All</div><div class="mh">Open</div><div class="mh">Closed</div>'
    +'<div class="mc l">Total</div><div class="mc">'+pill(totAll,"tot")+'</div><div class="mc">'+pill(totOpen)+'</div><div class="mc">'+pill(totClosed)+'</div>';
  rows.forEach(function(u){
    h+='<div class="mc l">'+esc(u)+'</div><div class="mc">'+pill(stat[u].all)+'</div><div class="mc">'+pill(stat[u].open)+'</div><div class="mc">'+pill(stat[u].closed)+'</div>';
  });
  h+='</div></div>';
  return h;
}

function accountsTable(accts){
  if(!accts.length) return '<div class="acct-empty">No billing accounts for the selected location.</div>';
  var h='<table><thead><tr><th>Vendor</th><th>Billing Account</th><th>Utility</th><th>Last Bill</th><th>Open/Closed</th><th>Locations</th><th>Service Address</th><th>Details</th></tr></thead><tbody>';
  accts.forEach(function(a){
    var isOpen=String(a["Open/Closed"]||"").toLowerCase().indexOf("open")>-1 || String(a["Open/Closed"]||"").toLowerCase()==="active";
    var badge='<span class="badge '+(isOpen?"open":"closed")+'">'+esc(a["Open/Closed"]||"Unknown")+'</span>';
    h+='<tr>'
      +'<td>'+esc(a.Vendor)+'</td>'
      +'<td>'+esc(a["Billing Account"])+'</td>'
      +'<td>'+esc(a.Utility)+'</td>'
      +'<td class="lastbill">'+esc(a["Last Bill"]||"-")+'</td>'
      +'<td>'+badge+'</td>'
      +'<td>'+esc(a.Locations||"")+'</td>'
      +'<td>'+esc(a["Service Address"]||"")+'</td>'
      +'<td class="link">Bill History</td>'
      +'</tr>';
  });
  h+='</tbody></table>';
  return h;
}

function hierPopHtml(){
  if(!hopen) return '';
  var opts=ROOTS.map(function(r){
    var on=(selRoot===r.id);
    return '<div class="hopt'+(on?" on":"")+'" data-root="'+esc(r.id)+'"><span>'+esc(r.label)+'</span>'+(on?'<span class="ck">✓</span>':'')+'</div>';
  }).join('');
  return '<div class="hpop" id="hpop">'+opts+'</div>';
}

function render(){
  var m=appsmith.model||{};
  buildTree();

  var curRoot=(selRoot!=null)?NODES[selRoot]:null;
  // by default select the current hierarchy root so its accounts show on load
  if(!autoSelDone && curRoot && !selId){ autoSelDone=true; doSelect(curRoot.id); }
  var curLabel=curRoot?curRoot.label:"Select hierarchy";
  var topbar='<div class="topbar"><div class="hsel"><button class="hbtn" id="hbtn">'+esc(curLabel)+' <span class="chev">▾</span></button>'+hierPopHtml()+'</div></div>';

  // left
  var treeHtml;
  if(!ROOTS.length) treeHtml='<div class="placeholder">No hierarchy for this customer.</div>';
  else if(!curRoot) treeHtml='<div class="placeholder">Select a hierarchy above.</div>';
  else treeHtml=renderNode(curRoot,0);
  var left='<div class="left"><div class="search"><div class="box">'+SEARCH+'<input id="srch" placeholder="Search for a Location" value="'+esc(search)+'"/></div></div>'
    +'<div class="tree" id="tree">'+treeHtml+'</div></div>';

  // right
  var rbody;
  var selNode=(selId!=null)?NODES[selId]:null;
  if(rightTab==="details"){
    if(!selNode){ rbody='<div class="placeholder">Select a node from the tree to view its details.</div>'; }
    else {
      var gc=groupCounts(selNode);
      var totalLoc=Number((m.totalLocations&&m.totalLocations[0]&&(m.totalLocations[0].count||m.totalLocations[0].COUNT))||0);
      var unassigned=Math.max(0, totalLoc - gc.nestedLocs);
      function drow(k,v){ return '<div class="drow"><span class="dk">'+esc(k)+'</span><span class="dv">'+v+'</span></div>'; }
      rbody='<div class="details"><h3>'+esc(selNode.label)+' Location Group Details</h3>'
        +drow("Direct Groups", gc.directGroups)
        +drow("Direct Child Locations", gc.directLocs)
        +drow("Nested Groups", gc.nestedGroups)
        +drow("Nested Locations", gc.nestedLocs)
        +drow("Unassigned Locations", unassigned)
        +'</div>';
    }
  } else if(!selId){
    rbody='<div class="placeholder">Select a location from the tree to view its accounts.</div>';
  } else if(loadingAcct || m.accountsLoading){
    rbody='<div class="placeholder">Loading accounts…</div>';
  } else {
    var accts=(m.accounts||[]);
    rbody=commonMatrix(accts)+accountsTable(accts);
  }
  var right='<div class="right"><div class="subtabs">'
    +'<div class="subtab'+(rightTab==="accounts"?" on":"")+'" data-tab="accounts">Accounts</div>'
    +'<div class="subtab'+(rightTab==="details"?" on":"")+'" data-tab="details">Location Details</div>'
    +'</div><div class="rbody">'+rbody+'</div></div>';

  var root=document.getElementById("root"); if(!root) return;
  root.innerHTML='<div class="wrap">'+topbar+'<div class="panes">'+left+right+'</div></div>';
  bind();
}

function doSelect(id){
  var n=NODES[id]; if(!n) return;
  selId=id; selLabel=n.label; expanded[id]=true; loadingAcct=true;
  appsmith.updateModel({ selIds: leafIds(n).join(","), selLabel: n.label });
  appsmith.triggerEvent("onSelectNode");
}

function pickHierarchy(id){
  if(selRoot!==id){ selRoot=id; expanded[id]=true; doSelect(id); }
  hopen=false; render();
}

function selectNode(id){
  var n=NODES[id]; if(!n) return;
  // click an already-selected node -> unselect and clear the accounts view
  if(selId===id){
    selId=null; selLabel="";
    appsmith.updateModel({ selIds: "", selLabel: "" });
    render();
    return;
  }
  doSelect(id);
  render();
}

function bind(){
  var hb=document.getElementById("hbtn");
  if(hb) hb.onclick=function(ev){ ev.stopPropagation(); hopen=!hopen; render(); };
  var hp=document.getElementById("hpop");
  if(hp){ var os=hp.querySelectorAll("[data-root]");
    for(var a=0;a<os.length;a++){ (function(el){ el.onclick=function(){ pickHierarchy(el.getAttribute("data-root")); }; })(os[a]); } }
  var s=document.getElementById("srch");
  if(s) s.oninput=function(e){ search=e.target.value; var pos=e.target.selectionStart; render(); var s2=document.getElementById("srch"); if(s2){ s2.focus(); try{s2.setSelectionRange(pos,pos);}catch(_){} } };
  var tw=document.querySelectorAll("[data-tw]");
  for(var i=0;i<tw.length;i++){ (function(el){ el.onclick=function(ev){ ev.stopPropagation(); var id=el.getAttribute("data-tw"); expanded[id]=!expanded[id]; render(); }; })(tw[i]); }
  var rows=document.querySelectorAll(".row[data-id]");
  for(var j=0;j<rows.length;j++){ (function(el){ el.onclick=function(){ selectNode(el.getAttribute("data-id")); }; })(rows[j]); }
  var tabs=document.querySelectorAll("[data-tab]");
  for(var k=0;k<tabs.length;k++){ (function(el){ el.onclick=function(){ rightTab=el.getAttribute("data-tab"); render(); }; })(tabs[k]); }
}

appsmith.onReady(function(){ render(); appsmith.onModelChange(function(){ loadingAcct=false; render(); }); });
